+				not be confirmed due to error. Your payment has been refunded.
+			</Text>
+			<SignOff close="Best" />
+		</EmailLayout>
+	);
+}
+
+WorkshopRegistrationErrorEmail.PreviewProps = {
+	WORKSHOP_NAME: 'Longsword Fundamentals',
+} satisfies WorkshopRegistrationErrorProps;

