describe('inviteMember', () => {
	it('renders the invitation copy with the acceptance link', async () => {
		const html = await render(
			<InviteMemberEmail INVITATION_LINK={INVITATION_LINK} />,
		);

		expect(html).toContain('invited to join DHC');
		expect(html).toContain(`href="${INVITATION_LINK}"`);
		expect(html).toContain('expires in 7 days');
		expect(html).toContain('HEMA Ireland');
		expect(html).toContain('Dublin HEMA Club');
	});

	it('greets plainly even when names are provided (faithful port)', async () => {
		const html = await render(
			<InviteMemberEmail
				INVITATION_LINK={INVITATION_LINK}
