input.newString:
/**
 * Brand colour tokens from the Dublin HEMA Club design system
 * (design-system/dublin-hema-club/MASTER.md). Hex values, because email
 * clients do not reliably support oklch()/hsl() custom properties.
 */
export const colors = {
	/** --color-primary (heritage navy) */
	primary: '#1f4f85',
	/** --color-on-primary */
	onPrimary: '#ffffff',
	/** --color-secondary / ring (brand gold) */
	secondary: '#e5b524',
	/** --color-background (parchment) */
	background: '#f8f5ee',
	/** --color-foreground (navy black) */
	foreground: '#121827',
	/** --color-muted-foreground equivalent for secondary copy */
	mutedForeground: '#5c6a82',
	/** --color-border */
	border: '#bec4cf',
	/** --color-card (near-white surface) */
	card: '#fffdf8',
} as const;

const body: React.CSSProperties = {
	backgroundColor: colors.background,
	fontFamily:
		'"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
	margin: 0,
};

const container: React.CSSProperties = {
	margin: '0 auto',
	maxWidth: '600px',
	padding: '24px',
};

const card: React.CSSProperties = {
	backgroundColor: colors.card,
	border: `1px solid ${colors.border}`,
	borderRadius: '12px',
	padding: '32px',
};

const text: React.CSSProperties = {
	color: colors.foreground,
	fontSize: '16px',
	lineHeight: '26px',
	margin: '0 0 20px',
};

/** Shared paragraph style so every template's body copy matches. */
export const paragraphStyle = text;

/** Link + button styling in the heritage navy every CTA uses. */
export const linkStyle: React.CSSProperties = {
	color: colors.primary,
};

/**
 * Primary button matching the design system's `.btn-primary`.
 * Padding lives on an inner span for Outlook via React Email's Button.
 */
export const buttonStyle: React.CSSProperties = {
	backgroundColor: colors.primary,
	borderRadius: '8px',
	color: colors.onPrimary,
	display: 'inline-block',
	fontSize: '16px',
	fontWeight: 600,
	margin: '0 0 20px',
	padding: '12px 24px',
	textDecoration: 'none',
};

/**
 * Shared shell for all DHC transactional emails: parchment background,
 * Inter type, one centered white card with a soft border — the same look
 * as the dashboard's card surfaces.
 *
 * Lives in an underscore-prefixed folder so the `email dev` preview does
 * not list it as a template.
 */
export function EmailLayout({ preview = 'Dublin HEMA Club', children }: EmailLayoutProps) {
	return (
		<Html lang="en">
			<Preview>{preview}</Preview>
			<Body style={body}>
				<Container style={container}>
					<div style={card}>{children}</div>
				</Container>
			</Body>
		</Html>
	);
}

